        df2b = compute_delta_f(f'F_p_{j}_m', f'E_2d_{j}')
        g2b = gamma[(f'F_p_{j}_m', f'E_2d_{j}')]

        # Check H_(j) projection vs H_{n+1} projection:
        # In gamma:
