        print('  g2a on F_p_j_m:', g2a.get(f'F_p_{j}_m', 0))
        print('  g2b on H_{n+1}:', g2b.get(f'H_{n+1}', 0))
        print('  df2a on F_p_j_m:', df2a.get(f'F_p_{j}_m', 0))
